<?php namespace Workspace; ?><section class="panel inset"><form method="get" class="inline"><input type="hidden" name="p" value="approved_acts"><label>Проект<select name="project" required><option value="">Выберите проект</option><?php selectOptions($projects,$selected) ?></select></label><button>Открыть</button></form></section><?php if($selected): ?><section class="panel inset"><h2>Согласованные акты</h2><p>Только актуальные утверждённые акты разрешённого проекта. Не является подтверждением внешней электронной подписи.</p><?php foreach(array_slice($rows,0,50) as $r): ?><div class="splitrow"><div><?= h($r['title'].' v'.$r['revision']) ?><small><?= h($r['document_hash']) ?></small></div><a href="<?= h(url('prep.act',['project'=>$selected,'id'=>$r['id']])) ?>">Скачать PDF</a></div><?php endforeach ?><?php if(count($rows)>50): ?><a href="<?= h(url('approved_acts',['project'=>$selected,'before'=>$rows[49]['id']])) ?>">Следующие 50</a><?php endif ?><?php if(!$rows): ?><p>Нет согласованных актов.</p><?php endif ?></section><?php endif ?>
